    """Identify the main rectangular outline and mark missing outline pixels."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # For every pair of foreground rows, complete their intervening column
    # only when both row endpoints indicate the same vertical outline column.
    # Likewise complete horizontal spans between neighboring marked edges.
    # Color only missing cells on the inferred outline, preserving given marks.
    rows_by_col = {c: [r for r in range(h) if grid[r][c] == fg] for c in range(w)}
    for c, rows in rows_by_col.items():
        for a, b in zip(rows, rows[1:]):
            if b > a + 1:
                for r in range(a + 1, b):
                    # restrict vertical continuation to gaps where that row
                    # has no foreground point in the same vertical section
                    out[r][c] = 2

    # Horizontal spans are only between contiguous structure endpoints at
    # the topmost or bottommost row of the pattern.
    occupied = [r for r in range(h) if any(grid[r][c] == fg for c in range(w))]
    if occupied:
        for r in (min(occupied), max(occupied)):
            cols = [c for c in range(w) if grid[r][c] == fg]
            if len(cols) > 1:
                for c in range(min(cols), max(cols) + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
