 "content": "def transform(grid):
    """Fill gaps in long aligned runs; also complete the bottom horizontal edge."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foreground = next(value for value in counts if value != background)
    out = [row[:] for row in grid]

    occupied_rows = [r for r in range(h) if any(grid[r][c] == foreground for c in range(w))]
    bottom = max(occupied_rows)

    # Long rows are horizontal strokes. The bottom edge is also completed
    # when its two endpoints are visible.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == foreground]
        if len(cols) >= 3 or (r == bottom and len(cols) >= 2):
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Repeated columns are vertical strokes; require three or more original
    # points so isolated pairs are not accidentally joined.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == foreground]
        if len(rows) >= 3:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    return out
